import{describe,it,expect}from"vitest";import{CONSTITUTION_MILESTONES,filterMilestones,calculateTimelineProgress,getMilestoneStats}from"../../frontend/constitution-timeline/constitution-timeline.js";describe("Constitution Timeline Dataset Integrity",()=>{it("contains at least 8 verified constitutional milestones (contains 11)",()=>{expect(CONSTITUTION_MILESTONES.length).toBeGreaterThanOrEqual(8),expect(CONSTITUTION_MILESTONES.length).toBe(11)}),it("verifies strict chronological ordering of all milestones",()=>{for(let e=0;e<CONSTITUTION_MILESTONES.length-1;e++){const t=new Date(CONSTITUTION_MILESTONES[e].date),i=new Date(CONSTITUTION_MILESTONES[e+1].date);expect(t.getTime()).toBeLessThanOrEqual(i.getTime())}}),it("every milestone contains required fields (id, date, displayDate, title, era, summary, details, keyFigures)",()=>{CONSTITUTION_MILESTONES.forEach((e,t)=>{expect(e,`Milestone at index ${t} missing id`).toHaveProperty("id"),expect(e,`Milestone at index ${t} missing date`).toHaveProperty("date"),expect(e,`Milestone at index ${t} missing displayDate`).toHaveProperty("displayDate"),expect(e,`Milestone at index ${t} missing title`).toHaveProperty("title"),expect(e,`Milestone at index ${t} missing era`).toHaveProperty("era"),expect(e,`Milestone at index ${t} missing summary`).toHaveProperty("summary"),expect(e,`Milestone at index ${t} missing details`).toHaveProperty("details"),expect(e,`Milestone at index ${t} missing keyFigures`).toHaveProperty("keyFigures"),expect(typeof e.title).toBe("string"),expect(e.title.trim().length).toBeGreaterThan(0),expect(typeof e.summary).toBe("string"),expect(e.summary.trim().length).toBeGreaterThan(0),expect(typeof e.details).toBe("string"),expect(e.details.trim().length).toBeGreaterThan(0),expect(Array.isArray(e.keyFigures)).toBe(!0),expect(e.keyFigures.length).toBeGreaterThan(0)})}),it("maintains objective, neutral framing without partisan language",()=>{const e=["corrupt","illegal","scam","tyrannical","heroic"];CONSTITUTION_MILESTONES.forEach(t=>{const i=`${t.title} ${t.summary} ${t.details}`.toLowerCase();e.forEach(e=>{expect(i).not.toContain(e)})})})}),describe("Milestone Filtering Engine",()=>{it("filters milestones by era category correctly",()=>{const e=filterMilestones(CONSTITUTION_MILESTONES,"foundational");expect(e.length).toBe(4),e.forEach(e=>expect(e.era).toBe("foundational"));const t=filterMilestones(CONSTITUTION_MILESTONES,"amendments");expect(t.length).toBe(4),t.forEach(e=>expect(e.era).toBe("amendments"));const i=filterMilestones(CONSTITUTION_MILESTONES,"modern");expect(i.length).toBe(3),i.forEach(e=>expect(e.era).toBe("modern"))}),it("filters milestones by search query keyword",()=>{const e=filterMilestones(CONSTITUTION_MILESTONES,"all","Ambedkar");expect(e.length).toBe(1),expect(e[0].id).toBe("m2");const t=filterMilestones(CONSTITUTION_MILESTONES,"all","GST");expect(t.length).toBe(1),expect(t[0].id).toBe("m10")}),it("returns all milestones when era is all and search is empty",()=>{const e=filterMilestones(CONSTITUTION_MILESTONES,"all","");expect(e.length).toBe(11)})}),describe("Scroll Progress Math",()=>{it("computes 0% when scrollTop is 0",()=>{expect(calculateTimelineProgress(0,2e3,1e3)).toBe(0)}),it("computes 50% when scrolled halfway",()=>{expect(calculateTimelineProgress(500,2e3,1e3)).toBe(50)}),it("computes 100% when scrolled to bottom",()=>{expect(calculateTimelineProgress(1e3,2e3,1e3)).toBe(100)}),it("handles zero or negative scroll height gracefully",()=>{expect(calculateTimelineProgress(100,500,500)).toBe(100),expect(calculateTimelineProgress(0,0,0)).toBe(100)})}),describe("Milestone Stats Aggregator",()=>{it("returns correct stats breakdown for the dataset",()=>{const e=getMilestoneStats(CONSTITUTION_MILESTONES);expect(e.total).toBe(11),expect(e.foundationalCount).toBe(4),expect(e.amendmentsCount).toBe(4),expect(e.modernCount).toBe(3),expect(e.startDate).toBe("December 9, 1946"),expect(e.endDate).toBe("Present Day")})});